INSERT INTO `feedback` VALUES (1,NULL,NULL,'Napakabait ng doctor pero ang tagal ng waiting time',3,'2026-07-13 16:11:53'),(2,NULL,NULL,'The doctor was very accommodating and explained everything clearly.',5,'2026-07-14 01:15:00'),(3,NULL,NULL,'The waiting time was a bit long but the service was good.',4,'2026-07-14 01:30:00'),(4,NULL,NULL,'Friendly staff and clean clinic.',5,'2026-07-14 01:45:00'),(5,NULL,NULL,'The consultation felt rushed.',3,'2026-07-14 02:00:00'),(6,NULL,NULL,'Excellent experience from check-in to consultation.',5,'2026-07-14 02:15:00'),(7,NULL,NULL,'The nurse was very helpful and polite.',4,'2026-07-14 02:30:00'),(8,NULL,NULL,'Appointment started on time. Great service!',5,'2026-07-14 02:45:00'),(9,NULL,NULL,'The clinic was crowded and had a long queue.',2,'2026-07-14 03:00:00'),(10,NULL,NULL,'Doctor answered all my questions patiently.',5,'2026-07-14 03:15:00'),(11,NULL,NULL,'Overall good experience, but parking was difficult.',4,'2026-07-14 03:30:00'),(12,NULL,NULL,'The receptionist was courteous and helpful.',5,'2026-07-14 03:45:00'),(13,NULL,NULL,'Had to wait over an hour before being called.',2,'2026-07-14 04:00:00'),(14,NULL,NULL,'Professional doctor and very informative consultation.',5,'2026-07-14 04:15:00'),(15,NULL,NULL,'Facilities were clean and organized.',4,'2026-07-14 04:30:00'),(16,NULL,NULL,'Expected a faster process.',3,'2026-07-14 04:45:00'),(17,NULL,NULL,'The doctor listened carefully to my concerns.',5,'2026-07-14 05:00:00'),(18,NULL,NULL,'Very satisfied with the medical care provided.',5,'2026-07-14 05:15:00'),(19,NULL,NULL,'Service was okay but could be improved.',3,'2026-07-14 05:30:00'),(20,NULL,NULL,'Staff were friendly and professional.',4,'2026-07-14 05:45:00'),(21,NULL,NULL,'Highly recommended clinic. Will definitely come back.',5,'2026-07-14 06:00:00'),(22,NULL,NULL,'Mabait naman yung doctor at in-explain nang maayos yung condition ko. Satisfied ako.',5,'2026-07-15 01:00:00'),(23,NULL,NULL,'Okay yung service pero medyo matagal yung waiting time. Sana mas mabilis next time.',4,'2026-07-15 01:30:00'),(24,NULL,NULL,'Friendly yung staff pero medyo nalito ako sa process ng registration.',3,'2026-07-15 02:00:00'),(25,NULL,NULL,'Super bait ng nurse at very accommodating sila. Comfortable yung buong visit ko.',5,'2026-07-15 02:30:00'),(26,NULL,NULL,'Maayos yung consultation pero medyo crowded yung clinic. Overall okay pa rin.',4,'2026-07-15 03:00:00'),(27,2,NULL,'Service ay mabagal',3,'2026-07-20 09:13:42'),(28,35,NULL,'I liked how the doctors treated me',5,'2026-07-20 15:37:08'),(29,39,NULL,'Good service, im satisfied',5,'2026-07-20 20:07:16'),(30,43,NULL,'Good service',5,'2026-07-20 20:08:08'),(31,47,NULL,'Good service, im deeply satified',5,'2026-07-20 20:17:17'),(32,79,NULL,'Sana mas mabilis ang process next time.',3,'2026-07-21 01:14:49'),(33,85,NULL,'submit review/rating',0,'2026-07-21 01:19:55'),(34,89,NULL,NULL,3,'2026-07-21 01:20:20'),(35,93,NULL,NULL,5,'2026-07-21 01:22:07'),(36,99,NULL,'sobrang slay niyo',5,'2026-07-21 03:45:59'),(37,124,NULL,'maganda ang serbisyo, mabait ang staffs',5,'2026-08-24 09:21:53'),(38,147,NULL,NULL,4,'2026-08-26 08:31:09'),(39,153,NULL,'HINDI MAGANDA ANG SERVICE',4,'2026-08-26 08:32:53'),(40,157,NULL,NULL,5,'2026-09-01 16:23:24'),(41,161,NULL,'super satisfied ako sa service niyo',5,'2026-09-05 16:01:16'),(42,168,NULL,'di na ako babalik',1,'2026-09-06 17:33:23'),(43,210,18,'Ang tagal, paki improve.',1,'2026-09-09 08:14:28'),(44,214,NULL,NULL,5,'2026-09-15 03:03:47'),(45,220,NULL,'ang gagaling ng doctors',5,'2026-09-15 03:05:12'),(46,238,19,'medyo mabagal pero sobrang nice ng nurses',3,'2026-09-17 03:16:09'),(47,245,NULL,'the best ang doctors dito, sobrang patient',5,'2026-09-17 04:44:29'),(48,283,20,NULL,5,'2026-09-25 11:37:28');
